function validate([edges]) {
  if (!Array.isArray(edges)) return 'edges must be a list of [u, v] pairs.';
  const n = edges.length;
  if (n < 3 || n > 1000) return 'edges needs 3 to 1000 pairs.';
  const seen = new Set();
  const inDegree = new Array(n + 1).fill(0);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || !edge.every(x => Number.isInteger(x) && x >= 1 && x <= n)) return 'Each edge is [u, v] with both nodes between 1 and n.';
    if (edge[0] === edge[1]) return 'An edge cannot point from a node to itself.';
    const key = edge[0] * 4096 + edge[1];
    if (seen.has(key)) return 'The same edge appears twice.';
    seen.add(key);
    inDegree[edge[1]]++;
  }
  // Weakly connected after leaving out edge number skip (or none)?
  const connectedWithout = skip => {
    const leader = Array.from({ length: n + 1 }, (_, i) => i);
    const find = x => { while (leader[x] !== x) { leader[x] = leader[leader[x]]; x = leader[x]; } return x; };
    let parts = n;
    edges.forEach(([u, v], i) => { if (i === skip) return; const a = find(u), b = find(v); if (a !== b) { leader[b] = a; parts--; } });
    return parts === 1;
  };
  const bad = 'The edges must form a rooted tree plus one extra edge.';
  const doubled = [];
  for (let x = 1; x <= n; x++) if (inDegree[x] > 2) return bad; else if (inDegree[x] === 2) doubled.push(x);
  if (doubled.length > 1) return bad;
  if (doubled.length === 0) return connectedWithout(-1) ? null : bad;
  const into = [];
  edges.forEach(([, v], i) => { if (v === doubled[0]) into.push(i); });
  return into.some(i => connectedWithout(i)) ? null : bad;
}

