function findRedundantDirectedConnection(edges) {
  const n = edges.length;
  const incoming = new Array(n + 1).fill(-1);
  let first = -1;
  let second = -1;
  for (let i = 0; i < n; i++) {
    const child = edges[i][1];
    if (incoming[child] === -1) {
      incoming[child] = i;
    } else {
      first = incoming[child];
      second = i;
    }
  }

  const leader = Array.from({ length: n + 1 }, (_, node) => node);
  const find = (node) => {
    while (leader[node] !== node) {
      leader[node] = leader[leader[node]];
      node = leader[node];
    }
    return node;
  };

  for (let i = 0; i < n; i++) {
    if (i === second) continue;
    const [u, v] = edges[i];
    const rootU = find(u);
    const rootV = find(v);
    if (rootU === rootV) {
      return first !== -1 ? edges[first] : edges[i];
    }
    leader[rootV] = rootU;
  }
  return edges[second];
}

