function findRedundantDirectedConnection(edges) {
  // Try removing each edge, latest first, and test whether a rooted tree remains.
  const n = edges.length;
  for (let skip = n - 1; skip >= 0; skip--) {
    const children = Array.from({ length: n + 1 }, () => []);
    const parents = new Array(n + 1).fill(0);
    edges.forEach(([u, v], i) => {
      if (i !== skip) {
        children[u].push(v);
        parents[v]++;
      }
    });
    if (parents.some(c => c > 1)) continue;
    const roots = [];
    for (let x = 1; x <= n; x++) if (parents[x] === 0) roots.push(x);
    if (roots.length !== 1) continue;
    const reached = new Set([roots[0]]);
    const stack = [roots[0]];
    while (stack.length) {
      const x = stack.pop();
      for (const y of children[x]) if (!reached.has(y)) { reached.add(y); stack.push(y); }
    }
    if (reached.size === n) return edges[skip];
  }
  return null;
}

