function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(101) : 3 + pick(6);
  const labels = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [labels[i], labels[j]] = [labels[j], labels[i]]; }
  // A random tree: chain-like, star-like or fully random, depending on the roll.
  const shape = rand();
  const edges = [];
  const present = new Set();
  for (let i = 1; i < n; i++) {
    const p = shape < 0.25 ? i - 1 : shape < 0.4 ? 0 : shape < 0.6 ? Math.max(0, i - 1 - pick(3)) : pick(i);
    edges.push([labels[p], labels[i]]);
    present.add(labels[p] * 4096 + labels[i]);
  }
  // The extra edge: sometimes into the root (a cycle without a two-parent node), otherwise anywhere new.
  for (;;) {
    const u = 1 + pick(n);
    const v = rand() < 0.3 ? labels[0] : 1 + pick(n);
    if (u === v || present.has(u * 4096 + v)) continue;
    edges.push([u, v]);
    break;
  }
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [edges];
}
